#!/usr/bin/env python3
"""Inspect actual published by-office CSV without collapsing authority/category keys."""
from pathlib import Path
import collections,csv,gzip,hashlib,io,json
D=Path(__file__).resolve().parent;N=D/'news'
def main():
 mf={a['id']:a for a in json.loads((N/'manifest.json').read_text())};a=mf['sos-2024-president-csv'];z=(N/a['asset']).read_bytes();b=gzip.decompress(z);assert hashlib.sha256(z).hexdigest()==a['stored_sha256'] and hashlib.sha256(b).hexdigest()==a['raw_sha256'];rr=list(csv.DictReader(io.StringIO(b.decode('utf-8-sig'))));counts=collections.Counter();j=collections.defaultdict(collections.Counter);units=collections.defaultdict(list);duplicate=collections.Counter()
 for i,r in enumerate(rr):
  counts[r['CandidateName']]+=int(r['VoteCount']);j[r['JurisdictionID']][(r['JurisContainerID'],r['JurisName'])]+=1;units[(r['JurisdictionID'],r['JurisContainerID'],r['JurisName'],r['PrecinctName'])].append(i);duplicate[(r['JurisdictionID'],r['PrecinctName'],r['EISCandidateID'])]+=1
 result={'status':'native_original_preflight_no_priority_accepted','source':a,'raw_rows':len(rr),'source_columns':list(rr[0]),'authority_IDs':len(j),'authority_container_name_contexts':sum(len(x) for x in j.values()),'source_native_contexts':len(units),'candidate_or_raw_category_sums':dict(counts),'authority_contexts':[{'JurisdictionID':k,'contexts':[{'JurisContainerID':a,'JurisName':b,'source_rows':v} for (a,b),v in c.items()]} for k,c in j.items()],'naive_authority_precinct_candidate_ID_duplicate_excess':sum(v-1 for v in duplicate.values()),'scope':['SourceJurisdictionID is not FIPS; county/city election authorities remain distinct.','City rows can use container0 or parentcountyID depending source categories; not extra county votes to sum blindly.','RawWrite-In case variants/under/over/blank remain original categories, not legally counted named candidates.','CandidateID0 can repeat across distinct noncandidate names; no deduplication or invented missing methods.','Registration repeats across candidates and categories; do not sum it repeatedly.','No actual2026geography, livefeed, outstandingvotes or acceptedexact80 implied.']};(D/'coordinator-primary-preflight.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['source','authority_contexts']},indent=2))
if __name__=='__main__':main()
